#include <atomic>
#include <iostream>
#include <utility>

template <class T>
class LockFreeStack {
    struct Node { T value; Node* next; };
    std::atomic<Node*> head_{nullptr};
public:
    void push(T v) {
        Node* n = new Node{std::move(v), nullptr};
        Node* old = head_.load(std::memory_order_relaxed);  // initial guess only
        do {
            n->next = old;
        } while (!head_.compare_exchange_weak(old, n,
                     std::memory_order_release,      // on success: publish
                     std::memory_order_relaxed));    // on failure: retry
    }
    // pop() deliberately omitted - see the ABA and reclamation discussion below.
};

int main() {
    LockFreeStack<int> s;
    s.push(1);
    s.push(2);
    std::cout << "pushed two nodes\n";
    return 0;
}

